# SageMaker HyperParameter Tuning Job with storage volume KMS encryption enabled
resource "aws_sagemaker_hyperparameter_tuning_job" "<example_resource_name>" {
  name = "<example_resource_name>"

  hyperparameter_tuning_job_config {
    strategy = "Bayesian"
    hyperparameter_tuning_job_objective {
      type        = "Maximize"
      metric_name = "<metric_name>"
    }
    resource_limits {
      max_number_of_training_jobs = 10
      max_parallel_training_jobs  = 2
    }
  }

  training_job_definition {
    role_arn = "<example_role_arn>"
    algorithm_specification {
      training_image      = "<example_ecr_image_uri>"
      training_input_mode = "File"
    }
    output_data_config {
      s3_output_path = "s3://<example_bucket>"
    }
    resource_config {
      instance_type     = "ml.m5.large"
      instance_count    = 1
      volume_size_in_gb = 10
      volume_kms_key_id = "<example_kms_key_arn>" # CRITICAL: Enables KMS encryption for storage volumes
    }
    stopping_condition {
      max_runtime_in_seconds = 3600
    }
  }
}
```
